create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.AVQ_WERBUNG_2 (
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_2 im DWH',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_2 ID wird verwendet für Beziehung Lager zu Verteilzentrum.',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer.',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel_2 - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Pruefziffer, Counter) Regel: Neuer Artikel_2 -> Counter +1.',
	DAT_AKTION_VON DATE NOT NULL COMMENT 'Werbung/Aktion_2 gültig ab',
	DAT_AKTION_BIS DATE NOT NULL COMMENT 'Werbung/Aktion_2 gültig bis',
	KJWO NUMBER(38,0) NOT NULL COMMENT 'Kalenderwoche',
	ANZ_TAGE_AKTION NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage Aktion_2',
	WTAG_ID_START NUMBER(38,0) NOT NULL COMMENT 'Wochentag (Aktion_2 von)',
	WTAG_ID_ENDE NUMBER(38,0) NOT NULL COMMENT 'Wochentag (Aktion_2 bis)',
	CLUSTER_DAUER_ID NUMBER(38,0) NOT NULL COMMENT 'Cluste für die Dauer, z. B. 1: 1 Tages-Aktionen, 2: 2-4 Tage (Wochenstart/-ende), 3: 5-9 Tage (Normal Wochenwerbung), 4: alles > 9 Tage',
	WERBEMITTEL_AVQ_TOP_PRIO_NR NUMBER(38,0) NOT NULL COMMENT 'Werbemittel (AVQ) mit der höchsten Priorität/ID',
	WERBEFLAECHENABSCHNITT_AVQ_TOP_PRIO_NR NUMBER(38,0) NOT NULL COMMENT 'Werbeflächenabschnitt (AVQ) mit der höchsten Priorität/ID',
	WERBEFLAECHENTHEMA_AVQ_TOP_PRIO_NR NUMBER(38,0) NOT NULL COMMENT 'Werbeflächenthema (AVQ) mit der höchsten Priorität/ID',
	ART_MUTTER_WB_ID NUMBER(38,0) NOT NULL COMMENT 'Artikel_2 ID Werbemutter',
	POSTEN_WB_ID VARCHAR(2) NOT NULL COMMENT 'Postenkennzeichen der Werbemutter',
	POSTEN_ID VARCHAR(2) NOT NULL COMMENT 'Postenkennzeichen des Einzelartikels',
	PMR_TOP_ART_FG NUMBER(38,0) NOT NULL COMMENT 'TOP-Artikel_2 Flag (PMR)',
	WERBEPROZESS_ID NUMBER(38,0) NOT NULL COMMENT '0 - keine Mengenberechnung, 1 - WBS TP1, 2 - WBS TP2, 3 - WBS TP1+2, 4 - F&R',
	AKTIONSKLASSIFIZIERUNG_ID VARCHAR(10) NOT NULL COMMENT 'SA/AF/BBY/irrelevant da gänzlich gelöscht oder gesperrt / k. Preisaktivierung…',
	AKTIONSKLASSIFIZIERUNG_DET_ID NUMBER(38,0) NOT NULL COMMENT 'Prospekt/K-Card-only/BBY/Kombi',
	WRG_ID VARCHAR(3) NOT NULL COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	BETRAG_VK_AKTION_BRUTTO NUMBER(38,3) NOT NULL COMMENT 'Verkaufspreis in Aktion_2',
	BETRAG_VK_KCARD_BRUTTO NUMBER(38,3) NOT NULL COMMENT 'Verkaufspreis in Aktion_2 für K-CARD Kunden',
	BETRAG_VOR_AKTION_BRUTTO NUMBER(38,3) COMMENT 'Verkaufspreis vor Aktion_2',
	FAKTOR_FLAKI NUMBER(38,6) NOT NULL COMMENT 'Umrechnungsfaktor Flasche in Kiste. (Flasche/Kiste)',
	MHD_ZEITRAUM NUMBER(38,0) NOT NULL COMMENT 'Dieses Feld gibt den standardmaessigen Mindesthaltbarkeitszeitraum für diesen Artikel_2 in Tagen an (wird redundant aus der Tabelle art_2 geladen).',
	PRZ_MIN_RESTLAUFZEIT_LAGER NUMBER(38,0) NOT NULL COMMENT 'Lagerprozentsatz. Gibt an, wieviel Prozent der Restlaufzeit noch nicht abgelaufen sein darf, wenn der Artikel_2 vom Lager ausgeliefert wird (wird redundant aus der Tabelle art_2 geladen).',
	MENGE_PLAN_WBS NUMBER(38,3) NOT NULL COMMENT 'Planmenge aus WBS',
	MENGE_PLAN_UPLOAD NUMBER(38,3) NOT NULL COMMENT 'Planmenge aus Upload ',
	WBS_ESTIMATION_ID NUMBER(38,0) NOT NULL COMMENT 'Estimation ID WBS',
	WBS_ADJUSTMENT_ID NUMBER(38,0) NOT NULL COMMENT 'Adjustment ID WBS',
	MENGE_BESTAND_AKTIONSSTART NUMBER(38,3) NOT NULL COMMENT 'Bestandsmenge zum Beginn der Aktion.',
	MENGE_BESTAND_AKTIONSENDE NUMBER(38,3) NOT NULL COMMENT 'Bestandsmenge am Ende der Aktion.',
	MENGE_UEBERBESTAND NUMBER(38,3) NOT NULL COMMENT 'Überbestand nach Aktion_2',
	MENGE_BESTAND_MIN_SICHERHEIT NUMBER(38,3) NOT NULL COMMENT 'Menge, die unterste Grenze für den Sicherheitsbestand angibt. angereichert aus art_wup_status_per_2 (MARC_2).',
	MENGE_BESTAND_SOLL_MAX NUMBER(38,3) NOT NULL COMMENT 'Maximaler Sollbestand (PRWOG) (wird redundant aus der Tabelle art_wup_nachschub_per_2 geladen).',
	MENGE_SOLLBESTAND NUMBER(38,3) NOT NULL COMMENT 'Sollbestand (wird redundant aus der Tabelle art_wup_status_per_2 geladen) (MARC_2).',
	ANZ_NULLBESTAND_GESAMT NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Nullbestand waehrend des Aktionszeitraums.',
	ANZ_NULLBESTAND_TAG1 NUMBER(38,0) NOT NULL COMMENT 'Anzahl Nullbestände am ersten Aktions-Wochentag für den Artikel_2, bei Gültigkeit > 1 Woche_2 können Werte > 1 entstehen (how many weeks of the promotion had zero stock on their first day)',
	ANZ_NULLBESTAND_TAG1BIS3 NUMBER(38,0) NOT NULL COMMENT 'Anzahl Nullbestand in den ersten drei Aktionstagen für den Artikel_2 innerhalb der Kalenderwoche (kjwo).',
	ANZ_MINUSBESTAND_GESAMT NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Minusbestand waehrend des Aktionszeitraums.',
	ANZ_MINUSBESTAND_TAG1 NUMBER(38,0) NOT NULL COMMENT 'Minusbestand am ersten Tag_2 des Aktionszeitraums.',
	ANZ_MINUSBESTAND_TAG1BIS3 NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Minusbestand während der ersten drei Tage des Aktionszeitraums.',
	ANZ_EXC209_GESAMT NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Nullbestand in Aktion_2',
	ANZ_EXC209_TAG1 NUMBER(38,0) NOT NULL COMMENT 'Nullbestand am 1. Tag_2 (F&R Exception)',
	ANZ_EXC209_TAG1BIS3 NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Nullbestand Tag_2 1-3 (F&R Exception)',
	ANZ_EXC214_GESAMT NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Negativbestand in Aktion_2 (F&R Exception)',
	ANZ_EXC214_TAG1 NUMBER(38,0) NOT NULL COMMENT 'Negativbestand am 1. Tag_2 (F&R Exception)',
	ANZ_EXC214_TAG1BIS3 NUMBER(38,0) NOT NULL COMMENT 'Anzahl Tage mit Negativbestand Tag_2 1-3 (F&R Exception)',
	MENGE_GESAMT NUMBER(38,3) NOT NULL COMMENT 'Absatz gesamt in Basis-ME',
	BETRAG_UMSATZ_GESAMT NUMBER(38,3) NOT NULL COMMENT 'Umsatz netto gesamt',
	MENGE_HISTORIE_AF NUMBER(38,3) NOT NULL COMMENT 'Durchschnittliche Abverkaufsmenge der letzten 6 aktionsfreien Wochen.',
	MENGE_NUR_TAG1 NUMBER(38,3) NOT NULL COMMENT 'Absatz Tag_2 1 in Basis-ME',
	MENGE_TAG_1_7BIS13 NUMBER(38,3) NOT NULL COMMENT 'Absatz Tag_2 1 bis 13 Uhr in Basis-ME',
	MENGE_WE_GESAMT NUMBER(38,3) NOT NULL COMMENT 'Wareneingang in der Werbewoche.',
	MENGE_WE_VOR_AKTION NUMBER(38,3) NOT NULL COMMENT 'Wareneingang vor Aktion_2',
	MENGE_WE_IN_AKTION NUMBER(38,3) NOT NULL COMMENT 'Wareneingang in der Werbewoche und der Vorwoche, nur zentrale Bestellarten.',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	ANGEBOT_TYP_CD VARCHAR(10) COMMENT 'Alphanumerischer Code des Angebotstyps. Da die Werte aus der Detailebene aggregiert werden, wird bei abweichenden Werten anhand einer festgelegten fachlichen Priorität entschieden, welcher Wert auf Kopfebene ausgewiesen wird.',
	AKTION_TYP_ID VARCHAR(4) COMMENT 'Gibt die Art_2 der Aktion_2 an (z. B. KDN = App-Promotion, KDP = personalisiert, KDI = externer Partner). Bei abweichenden Werten auf Detailebene wird der finale Wert für die Kopfebene anhand einer festgelegten fachlichen Priorität ermittelt.',
	GESCHAEFTSVORFALL_ID VARCHAR(2) COLLATE 'en-ci' COMMENT 'Eindeutige ID eines Geschäftsvorfalls (z. B. 01). Bei abweichenden Werten aus den zugrundeliegenden Detail-Datensätzen entscheidet eine_2 festgelegte fachliche Priorität über den ausgewiesenen Wert.',
	KONDITIONSART_ID VARCHAR(4) COMMENT 'Eindeutiger Fachschlüssel der Konditionsart. Bei abweichenden Werten auf Detailebene greift zur Aggregation auf die Kopfebene eine_2 festgelegte fachliche Prioritätsregel.',
	RABATT_TYP_ID NUMBER(38,0) COMMENT 'ID des Rabatt-Typs, die die Art_2 des gewährten Rabattes angibt (z. B. 1 = Normalpreis, 2 = Rabattpreis, 3 = Absoluter Rabatt). Bei abweichenden Werten auf Detailebene entscheidet eine_2 fachliche Priorität.',
	ANZ_BONUSKAUF_BEZAHLT NUMBER(38,0) COMMENT 'Gibt bei Bonuskäufen die Anzahl der Artikel_2 an, die bezahlt werden müssen. Zur Aggregation auf den Gesamt-Werbezeitraum wird hier die Summe (SUM) der zugehörigen Detailwerte gebildet.',
	ANZ_BONUSKAUF_KAUF NUMBER(38,0) COMMENT 'Gibt bei Bonuskäufen die Anzahl der Artikel_2 an, die gekauft werden müssen, um die Bedingung zu erfüllen. Zur Aggregation auf die Kopfebene wird die Summe (SUM) der Detailwerte gebildet.',
	ANZ_BONUSKAUF_GRATIS NUMBER(38,0) COMMENT 'Gibt bei Bonuskäufen die Anzahl der Artikel_2 an, die kostenlos erhalten werden. Da diese Tabelle aggregiert ist, wird hier die Summe (SUM) der Detailwerte ausgewiesen.',
	MENGE_BONUSKAUF_MIN NUMBER(38,5) COMMENT 'Gibt bei Bonuskäufen die absatzbezogene Mindestmenge an, die erreicht werden muss, um die Bonusbuy-Bedingung zu erfüllen. Bei abweichenden Detailwerten wird zur Aggregation das Maximum (MAX) ausgewiesen.',
	PROZ_BONUSKAUF_RABATT NUMBER(38,5) COMMENT 'Der prozentuale Rabatt bei einem Bonuskauf. Zur Aggregation auf den Gesamt-Werbezeitraum wird hier das Maximum (MAX) der Rabattprozente aus der Detailebene gebildet.',
	BETRAG_BONUSKAUF_RABATT NUMBER(38,5) COMMENT 'Der absolute Wert des Rabattes bei einem Bonuskauf. Da die Werte aus der Detailebene stammen, wird zur Aggregation auf die Kopfebene das Maximum (MAX) ausgewiesen.',
	LISTUNG_FG NUMBER(38,0) COMMENT 'Flag gibt an, ob für die Artikel_2-Markt-Kombination im gesamten Aktionszeitraum eine_2 Listung vorlag. (aus SAP WLK1_2) Durch die Aggregation auf den Gesamtzeitraum wird hier das Maximum der Tageswerte ausgewiesen. 1 = Listung lag an mindestens einem Tag_2 der Aktion_2 vor, 0 = keine Listung im gesamten Zeitraum.',
	constraint PK_AVQ_WERBUNG primary key (MANDANT_ID, WUP_ID, NB_ID, ART_ID, DAT_AKTION_VON, DAT_AKTION_BIS)
)COMMENT='AVQ(Abverkaufsquote) Basistabelle - Kennzahlen und wichtige Attribute auf Ebene Markt/Artikel_2/Werbezeitraum'
;
